import java.util.*;

class Solution {
    public List<List<Integer>> singleUseCombos(int[] coins, int target) {
        Arrays.sort(coins);
        List<List<Integer>> out = new ArrayList<>();
        go(coins, 0, target, new ArrayList<Integer>(), out);
        return out;
    }

    private void go(int[] coins, int start, int left, List<Integer> cur, List<List<Integer>> out) {
        if (left == 0) { out.add(new ArrayList<>(cur)); return; }
        for (int j = start; j < coins.length; j++) {
            if (coins[j] > left) break;                         // sorted: nothing later fits
            if (j > start && coins[j] == coins[j - 1]) continue; // avoid duplicate multisets
            cur.add(coins[j]);
            go(coins, j + 1, left - coins[j], cur, out);        // each coin used once
            cur.remove(cur.size() - 1);
        }
    }
}

