class Solution:
    def singleUseCombos(self, coins: List[int], target: int) -> List[List[int]]:
        coins = sorted(coins)
        out, cur = [], []
        def go(i, left):
            if left == 0: out.append(cur[:]); return
            for j in range(i, len(coins)):
                if j > i and coins[j] == coins[j - 1]: continue
                if coins[j] > left: break
                cur.append(coins[j]); go(j + 1, left - coins[j]); cur.pop()
        go(0, target)
        return out

