function singleUseCombos(coins, target) {
  const cnt = new Map(); for (const c of coins) cnt.set(c, (cnt.get(c) || 0) + 1);
  const vals = [...cnt.keys()].sort((a, b) => a - b), out = [];
  function go(i, left, cur) {
    if (left === 0) { out.push(cur.slice()); return; }
    if (i === vals.length) return;
    const v = vals[i];
    for (let use = 0; use <= cnt.get(v) && use * v <= left; use++) {
      for (let u = 0; u < use; u++) cur.push(v);
      go(i + 1, left - use * v, cur);
      for (let u = 0; u < use; u++) cur.pop();
    }
  }
  go(0, target, []);
  return out;
}
